CREATE OR REPLACE FUNCTION public.require_profile_completion() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.onboarding_completed=true AND OLD.onboarding_completed IS DISTINCT FROM true AND (NEW.gender IS NULL OR NEW.birthday IS NULL OR nullif(trim(NEW.city),'') IS NULL OR nullif(trim(NEW.neighborhood),'') IS NULL) THEN RAISE EXCEPTION 'Completa o género, a data de nascimento e a tua banda antes de concluir a inscrição'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.require_profile_completion() FROM PUBLIC, anon, authenticated; CREATE TRIGGER require_profile_completion BEFORE UPDATE OF onboarding_completed ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.require_profile_completion();
